'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const { InventoryService, InsufficientStockError, OrderStateError } = require('../src');

async function service(stock) {
  const svc = new InventoryService();
  for (const [sku, qty] of Object.entries(stock)) await svc.addStock(sku, qty);
  return svc;
}

test('concurrent reserves never oversell', async () => {
  const svc = await service({ a: 10 });
  const res = await Promise.allSettled(
    Array.from({ length: 40 }, (_, i) => svc.reserve(`o${i}`, [{ sku: 'a', qty: 1 }]))
  );
  assert.equal(res.filter(r => r.status === 'fulfilled').length, 10);
  assert.ok(res.filter(r => r.status === 'rejected').every(r => r.reason instanceof InsufficientStockError));
  assert.deepEqual(await svc.snapshot('a'), { sku: 'a', stock: 10, reserved: 10, sold: 0 });
});

test('concurrent retries with the same orderId hold once', async () => {
  const svc = await service({ a: 10 });
  await Promise.all(Array.from({ length: 5 }, () => svc.reserve('o1', [{ sku: 'a', qty: 2 }])));
  assert.equal((await svc.snapshot('a')).reserved, 2);
});

test('failed multi-item reserve holds nothing', async () => {
  const svc = await service({ a: 5, b: 0 });
  await assert.rejects(svc.reserve('o1', [{ sku: 'a', qty: 1 }, { sku: 'b', qty: 1 }]), InsufficientStockError);
  assert.equal((await svc.snapshot('a')).reserved, 0);
});

test('concurrent commit and release of the same order are consistent', async () => {
  const svc = await service({ a: 5 });
  await svc.reserve('o1', [{ sku: 'a', qty: 2 }]);
  await Promise.allSettled([svc.commit('o1'), svc.commit('o1'), svc.release('o1')]);
  const s = await svc.snapshot('a');
  assert.ok(s.reserved === 0 && s.reserved >= 0);
  assert.ok((s.sold === 2 && s.stock === 3) || (s.sold === 0 && s.stock === 5));
});

test('release of a committed order is rejected', async () => {
  const svc = await service({ a: 5 });
  await svc.reserve('o1', [{ sku: 'a', qty: 2 }]);
  await svc.commit('o1');
  await assert.rejects(svc.release('o1'), OrderStateError);
  assert.deepEqual(await svc.snapshot('a'), { sku: 'a', stock: 3, reserved: 0, sold: 2 });
});

test('expire skips committed and released orders', async () => {
  let t = 0;
  const svc = new InventoryService({ now: () => t, reservationTtlMs: 10 });
  await svc.addStock('a', 10);
  await svc.reserve('c', [{ sku: 'a', qty: 2 }]);
  await svc.reserve('r', [{ sku: 'a', qty: 1 }]);
  await svc.reserve('h', [{ sku: 'a', qty: 3 }]);
  await svc.commit('c');
  await svc.release('r');
  t = 100;
  assert.deepEqual(await svc.expire(), ['h']);
  assert.deepEqual(await svc.snapshot('a'), { sku: 'a', stock: 8, reserved: 0, sold: 2 });
});

test('expire concurrent with commit does not corrupt counters', async () => {
  let t = 0;
  const svc = new InventoryService({ now: () => t, reservationTtlMs: 10 });
  await svc.addStock('a', 10);
  await svc.reserve('o', [{ sku: 'a', qty: 2 }]);
  t = 100;
  await Promise.allSettled([svc.expire(), svc.commit('o')]);
  const s = await svc.snapshot('a');
  assert.equal(s.reserved, 0);
  assert.ok((s.sold === 2 && s.stock === 8) || (s.sold === 0 && s.stock === 10));
});
